const RETRY_LABEL: Readonly<Record<Translated, string>> = {
  it: 'Ripetizione delle domande che avevi sbagliato',
  es: 'Repetición de preguntas que fallaste',
  pl: 'Powtórka pytań z błędnymi odpowiedziami',
  tr: 'Yanlış yaptığınız soruların tekrarı',
};

function textFor(examKey: string, id: string, locale: string): FormatText | undefined {
  if (locale === 'en') return undefined;
  if (id === 'retry') {
    const label = RETRY_LABEL[locale as Translated];
    return label ? { label, description: null, fidelityNote: null } : undefined;
  }
  return FORMAT_TEXT[`${examKey}/${id}`]?.[locale as Translated];
}

/** A format's name in this language; the configuration's English name when there is no translation. */
export function formatLabel(examKey: string, blueprint: { id: string; label: string }, locale: string): string {
  return textFor(examKey, blueprint.id, locale)?.label ?? blueprint.label;
}

/** A format's description in this language; the configuration's English description when there is no translation. */
export function formatDescription(examKey: string, blueprint: { id: string; description: string }, locale: string): string {
  return textFor(examKey, blueprint.id, locale)?.description ?? blueprint.description;
}

/** How closely a format matches the real exam, in this language; the configuration's English note otherwise. */
export function formatFidelityNote(examKey: string, blueprint: { id: string; fidelityNote: string }, locale: string): string {
  return textFor(examKey, blueprint.id, locale)?.fidelityNote ?? blueprint.fidelityNote;
}
